pfUI.octoNotes = {
  { "1.1.77", {
    { "Old ClassicAPI? You'll be told", "OctoLauncher installs an older ClassicAPI (v1.15) with no damage meter. If that's yours, you get one chat line per character on how to get the newest: close the game, run Install pfUI Octo DLLs.bat in your pfUI folder (or the Octo DLL Installer), then start from OctoLauncher - it keeps your new ClassicAPI and doesn't swap it back." },
  } },
  { "1.1.76", {
    { "Pick your meter", "the top of /pfui Meters now has pfUI Octo / ClassicAPI / Blizzard. \"ClassicAPI\" (with ClassicAPI 1.22 or newer) puts our windows away and shows ClassicAPI's own damage meter - and the Windows page becomes its page: style, numbers, when it shows, bar height, gap, text size, class colours, pictures, opacity, with a live preview, plus unlock, new window and reset." },
    { "New hover panel on meter bars", "each spell with its picture and a bar in the player's class colour, then total, per second and share - no other add-ons' tooltip lines mixed in." },
    { "ClassicAPI's numbers in our windows are now opt-in", "(Meters Data), after a crash on one PC when ClassicAPI's meter window loaded. You get one chat line about the new choice the first time you log in with ClassicAPI 1.22. New file: restart the game fully once." },
  } },
  { "1.1.75", {
    { "Totem order", "OctoTotems > Bars > Layout has an Element order choice, so the bars can go Air, Water, Fire, Earth (or any order you like)." },
    { "Earthen Bulwark bar fixed", "it said 0% with a full bulwark. It now reads the integrity from the aura's stack count and from your debuffs too. /bulwark debug prints what the game reports, if it still looks wrong." },
  } },
  { "1.1.74", {
    { "OctoTotems error fixed", "the shield / weapon imbue reminder button had no font for its timer, so \"octototems.lua:952: Font not set\" repeated over and over. Every totem button now gets its font when it is made." },
    { "Website download fixed", "the Download ZIP button works again (the newest releases had the zip under another name)." },
  } },
  { "1.1.73", {
    { "Leftovers go up fast", "after you post full stacks, the Sell tab reads your bags again and puts what's left into the stack size (36 Bronze Bars, one stack of 20 posted, and it's ready to post the 16 left), like aux does. If smaller stacks still fit, it just lowers the number of stacks. The \"in your bags\" count now stays right after a post too." },
  } },
  { "1.1.72", {
    { "Sell tab, quicker", "a 1 by 1 button lists every item on its own (stack size 1, as many as you have). Full stacks uses the biggest stack the item makes. Sliders under Stack size and Number of stacks let you drag or wheel the numbers, and the stacks slider only goes as far as your bags allow." },
    { "Spam Buyout", "keep clicking Buyout and it buys the picked auction and moves to the next one down. A click while the last buy is still going through now waits its turn instead of being refused, and the pick never jumps back to the one being bought." },
  } },
  { "1.1.71", {
    { "Profile import no longer goes dead", "The Import button stays clickable, and a line above it says why a string can't go in yet. If the string is cut short (Discord splits long messages), it tells you to copy all of it or send it as a file. A string pasted with Discord's code block around it now imports too." },
    { "Profile strings read and write better", "A setting with a line break in it used to break the whole string, and now it comes through. One odd line is left out instead of refusing everything. Lists (totem sets, consumables lists, roll rules) keep their order when you share them." },
  } },
  { "1.1.70", {
    { "OctoTotems set editor", "the preview on the Bars and Sets pages is now a fixed grid, one row per element with every totem as an icon. Click one to put it in the set, click it again to take it out, and right-click to hide it on your bars. Nothing grows or shrinks when you hover. The chips on top pick which set you edit (green = the one your key throws). Reset set empties it so you can pick a new one, and New set, Make active and Throw it sit right under it." },
    { "The line under each page's big title no longer runs under the Find box", "It stops before it, a too-long line is cut with \"...\" (hover it for the whole text), and the longest lines (OctoTotems, OctoDoTs, Auctions) were made shorter so they show whole." },
  } },
  { "1.1.69", {
    { "OctoTotems, our own Call of Elements", "a new section for shamans. Four totem bars (fire, earth, water, air) side by side or each on its own, opening on hover, always or never, in any direction, with your own order and hidden totems. Each button shows its timer, a timer line, the cooldown in red once the totem is gone, a glow for the one that is down, red when you've walked out of its range, and a gold dot for the set's totems. Durations come from this server's own spell data (the 90 s Windfury Totem too)." },
    { "Totem sets", "one key throws the next totem that isn't down (or is out of range, or about to run out). With nampower the whole set is queued on one press. Enemy players switch to their class's set, and a set named after a boss is picked when you target it. Ctrl-click a totem to put it in the set; right-click a bar for sets, throw, recall and options." },
    { "Alerts and reminders", "10 / 5 seconds left, run out, destroyed, out of range, and \"all out of range - recall?\" with a glowing Totemic Recall button. Shield and weapon imbue reminders come with a button that puts them back on. The totem advisor lights Poison Cleansing, Disease Cleansing or Tremor when your group needs it." },
    { "Smart heals", "battle heal and best heal keys heal the most hurt member of your group with the smallest rank that covers it. With SuperWoW it does this without changing your target." },
    { "Earthen Bulwark is now part of OctoTotems", "and sticks under the totem bars at the same width (switch that off to place it anywhere)." },
    { "ClassicAPI", "(real totem slots, early deaths, time left, usable/mana), nampower (whole set in one press) and SuperWoW / UnitXP (range from where each totem was dropped), each with a plain fallback. /totems (and /coe while Call of Elements isn't loaded). New files: restart the game fully once." },
  } },
  { "1.1.68", {
    { "Earthen Bulwark bar for tank shamans", "with Elemental Weapons and Rockbiter, a small movable bar shows how full your earthen bulwark is (the server's own integrity %) and about how much it holds (up to 20% of your max health). It turns bright with an 8 s timer line while it is absorbing, and says x3 while you wear a shield. Unit Frames > Earthen Bulwark or /bulwark. New file: restart the game fully once." },
  } },
  { "1.1.67", {
    { "OctoDoTs: pick what shows", "at the top of the Target bar page, Show = Both, Bars only (no target bar) or Target bar only (the Cursive-style bars stay away and cost nothing; they still show in layout mode so you can move them)." },
  } },
  { "1.1.66", {
    { "Meters use ClassicAPI's new damage meter", "with ClassicAPI 1.22 or newer, the current fight and Overall take damage, DPS, healing, HPS, interrupts, dispels, damage taken, deaths and enemy damage taken straight from the DLL - less work for the game in big raids. Earlier fights, the breakdown, uptime, threat and every other display stay ours. ClassicAPI's own meter window stays hidden unless you want it (Meters > Data). New file: restart the game fully once." },
    { "/pfmetercheck", "(or the button on Meters > Data) prints our totals next to ClassicAPI's for the current fight (/pfmetercheck overall for all fights)." },
    { "Target bar, per spell", "right-click a spell's icon (in the preview or the spell grid) for its own glow, when it glows (running out, always, missing), glow colour, time text, number size and place, and animations when it runs out or is put on." },
    { "Target bar box", "it now has its box in layout mode even while switched off, a tidy fixed width (Look > Room for icons), and its tab sits right after General in OctoDoTs." },
  } },
  { "1.1.65", {
    { "OctoDoTs Target bar", "a movable row of your own DoTs and bleeds on your target (Rake, Rip, Moonfire, Insect Swarm, Faerie Fire...), each as its spell icon with the time left and a shade that drains as it runs out. First tab in OctoDoTs, off until you switch it on." },
    { "Pick by icon", "click a spell's icon to always track it (green, greyed while missing) or ignore it (red). Show all of yours or only the tracked ones; size, gap, direction, warning time and opacity. New file: restart the game fully once." },
  } },
  { "1.1.64", {
    { "Layout mode bar you can read and move", "a solid panel (nothing shows through it any more) with the clicks in a strip that is part of it. Drag an empty spot to put it anywhere; right-click it to send it back to the top." },
    { "Show: All pfUI Game", "with Move anything on, choose whether layout mode shows every box, only pfUI's frames, or only the game's and your picked frames." },
    { "Fixed", "red FadingFrame.lua:22 ... startTime errors in chat after layout mode with Move anything on (the zone name frames' own fade is paused while layout mode is open)." },
  } },
  { "1.1.63", {
    { "Move anything", "a switch in layout mode's top bar gives the game's own frames boxes too - quest tracker, quest timers, battleground score, raid warnings, error text, zone name, item link tooltip, follow text, zone map - with snapping, sizing and hiding. Off by default, so layout mode stays tidy; your places, sizes and opacity stay either way." },
    { "Pick a frame", "point at any frame of any add-on and press Enter (or /moveany <FrameName>) - it gets a box like ours." },
    { "Game windows", "Shift + drag the character window, spellbook, quest log, talents, trainers, vendors and more; they open there from then on." },
    { "Clearer layout mode bar", "grouped controls with headings, tooltips on everything, and the clicks always shown under it. Settings > Move anything has opacity per frame, your picked frames and moved windows. New files: restart the game fully once." },
  } },
  { "1.1.62", {
    { "Important enemy buffs on nameplates without SuperWoW", "buff names now also come from ClassicAPI or the buff's tooltip, so \"Important ones\" (Berserker Rage, Recklessness, Ice Block, Evasion...) works for everyone." },
    { "Your own important buffs", "Nameplates > Auras > Enemy buffs - add any buff you want treated as important (names separated by #)." },
  } },
  { "1.1.61", {
    { "/gear back", "puts the set you wore before this one back on - handy in a macro." },
    { "Set names in any capitals", "/gear equip caster finds \"Caster\"; /gear unequip says what it takes off." },
    { "/gear help", "every gear command, also in the ItemRack page's help box with ItemRack's macro calls (EquipSet, UnequipSet, ToggleSet)." },
    { "Shield comes back", "taking off a set with a two-hander puts your off hand back on too." },
  } },
  { "1.1.60", {
    { "Fixes the \"critical error #132\" crashes", "at login and after a /reload (for example after importing a profile): the game was running out of memory. pfUI and pfQuest hold about 290 MB of Lua memory, and Lua let its garbage pile up to twice that before cleaning - more during fights. Now a memory ceiling keeps it in check: out of a fight garbage may grow 64 MB, in a fight by your fight room, and never past 600 MB (Settings > Performance, both adjustable, on by default)." },
    { "Loading clean-up", "pfQuest's 32 MB of quest data no longer leaves its garbage behind while the game loads. New file: restart the game fully once." },
  } },
  { "1.1.59", {
    { "Smoother gear swaps", "a set swap reads your bags once a frame instead of once for every item it moves." },
    { "Closed bags stay quiet", "a closed bag window no longer redraws every slot (and reads every item's tooltip) each time your bags change - it catches up the moment you open it." },
    { "Lighter buff bars", "buff names are remembered until your buffs change, instead of read again every 0.4 seconds." },
    { "Druid stealth paging", "checked only when your buffs or form change (with ClassicAPI / SuperWoW's stealth check), not every frame." },
  } },
  { "1.1.58", {
    { "World map pieces in the right place, every zone", "the map reveal now follows the game's own map table for all 53 zones, checked against a render of the real map pictures. No more wrong or doubled pieces in Thalassian Highlands and OctoWoW's other zones (the 1.1.55 change is undone)." },
  } },
  { "1.1.57", {
    { "No freeze on instant gear swaps", "swapping a whole set changes every slot at once, and each change used to refresh the set buttons, heal prediction and durability right away - many times in one moment. Each now refreshes once, a fraction of a second after the swap." },
  } },
  { "1.1.56", {
    { "Quest tracker error fixed for real", "no more \"tracker.lua:282: attempt to index a nil value\". The real cause was the game's quest watch frame going missing (another add-on), and the tracker now copes without it." },
  } },
  { "1.1.55", {
    { "World map drawn right again", "OctoWoW's own zones (Thalassian Highlands and others) no longer show in wrong patches with ClassicAPI installed. The map reveal uses pieces that match the real map pictures." },
  } },
  { "1.1.54", {
    { "Quest tracker error fixed", "no more \"tracker.lua:281: attempt to index global 'pfQuestCompat'\" spam. pfQuest's files now keep their own copy of what they need, so another add-on clearing it can't break them." },
  } },
  { "1.1.53", {
    { "Gear sets swap at once", "every piece of a set goes on in the same click, as ItemRack does, so you can put on one set, do something and put on another straight away. Armour still waits for combat to end." },
  } },
  { "1.1.52", {
    { "Minimap preview fixed", "the zone name, clock, mail, tracking and the other buttons are back in the Map page's preview, so you can move them there again. The box stays smaller." },
  } },
  { "1.1.51", {
    { "Previews fold away", "every preview box has a clear \"Hide preview\" / \"Show preview\" button at the top right, so you can see the settings under it. The Minimap page's preview is now just the map, in a smaller box." },
    { "Clean minimap looks", "Clean square, Square in your class colour or accent colour, Clean round and Round in class colour come first - a crisp solid border of 1-6 px in black, class, accent or your own colour. The spell-art looks follow." },
    { "Side bar, tidied", "every button is the same neat box, zoom is a plain + / -, mail sits in a box of its own, and the strip behind them is off by default. The bar is its own setting now, so it goes with any look." },
    { "Tidier Minimap page", "plain two-column rows in sections (Display, Border, Buttons, Spell art) with dropdowns instead of tile grids." },
  } },
  { "1.1.50", {
    { "Minimap side bar", "tracking, mail, the battleground queue, zoom in / out and the addon buttons arrow in one tidy strip along any side of the map, all one size, no gaps. Try the look \"Clean, buttons at the side\", or set it up under Minimap > Buttons and text > Side bar." },
  } },
  { "1.1.49", {
    { "Cleaner mob info", "short Hits / Armor lines with what they mean in grey; a hit turns gold or red when it takes a big bite of your health; no more \"Resists: None\". MobStats' own yellow lines are hidden while ours are on." },
    { "Profession lines only for you", "skinning, herb and ore lines show only if you have that profession (Shift shows them anyway)." },
  } },
  { "1.1.48", {
    { "Where it drops", "item tooltips list who drops it (with zone and chance), where it is found and who sells it; Shift shows more. Left out when Atlas already names the boss." },
    { "Disenchants into", "what an item turns into, the Enchanting it needs and what that is worth at the auction house - always for enchanters, with Shift for everyone else." },
    { "Herbs, ore and skinning", "nodes and skinnable creatures show the skill they need against yours (trainer colours) and what they give." },
    { "Mob stats", "enemies show their armor (and how much of your damage it takes off), melee hits and speed, and their resists - MobStats built in." },
    { "Item level", "beside the item's name. Every part can be set to always / Shift / never under Quality of Life > Tooltip extras." },
  } },
  { "1.1.47", {
    { "Cash on delivery in one click", "a COD letter's button says Pay, and clicking the item or right-clicking the row pays and takes it at once." },
  } },
  { "1.1.46", {
    { "Cleaner pull line in the threat window", "\"Pull at 43.0k\" in plain white, and its bar fills with your threat towards the pull point - green with room, gold when close, red past it. Tanks see \"Lead on <name>\"." },
  } },
  { "1.1.45", {
    { "DoT Tracker rows stay put in a fight", "every enemy keeps its row and new ones join at the bottom, so clicking through them never makes the list jump; it sorts again when the fight ends. Switch: DoT Tracker > General > \"Lock the order in combat\"." },
  } },
  { "1.1.44", {
    { "Totem damage in combat text", "your totems' hits (Searing, Magma, Fire Nova...) now show, with their own switch, colour and area under Combat Text > Messages (\"Your totems' damage\"). Only your own totems, never another shaman's." },
  } },
  { "1.1.43", {
    { "Buyouts stay on track", "after a buyout the cheapest auction left of the same item is picked next, and auctions of the same price no longer swap places, so spamming Buyout walks down the cheap ones in order." },
    { "Pick several at once", "Shift + drag (or Shift + click) over rows. Browse buys them all, cheapest first; My bids bids on them all; My auctions cancels them all - one question, then one by one. Click the button again to stop." },
    { "Price colours like aux", "\"Of usual\" is blue (a steal), green (cheap), yellow (about usual), orange (dear) or red (far too dear), on Browse, Shopping and Deals." },
    { "Column heads explain themselves", "hover any head for what it holds; \"Of usual\" is wide enough to read." },
  } },
  { "1.1.42", {
    { "NPCs no longer click for you", "OctoLazy's \"Skip the menu\" (flight masters, vendors, bankers, battle masters) is now off unless you switch it on - /lazy NPCs & quests. It is switched off once for everyone, with a chat line saying where it is." },
    { "Map icons stay after a relog", "herb / ore / fish marks are no longer put back to old values by a UI layout switch, and the quest database's tracking lists (herbs, mines, rares...) come back by themselves a few seconds after you log in." },
  } },
  { "1.1.41", {
    { "OctoRinse (UpsiRinse built in)", "one key cures the most important debuff on your group with the right spell, in range. Its own section at the top of Combat & Items. Every UpsiRinse setting is there, and your UpsiRinse settings, lists and learned debuffs are copied over the first time both are loaded. New files: restart the game fully once." },
    { "Boss lists, per boss only", "every raid and dungeon from UpsiRinse with each boss's curable debuffs, under the zone's loading-screen art. Skip school / Hide / Cure first on a boss count only while you fight that boss - never in PvP or anywhere else. \"Everywhere\" holds the lists that count in every fight." },
    { "Quick menu in combat", "click the Players picture on the bar - class pictures, raid groups and every player. Left-click = cure first, right-click = never cure, plus My group first and Pets." },
    { "Faster with DLLs", "cures react the moment a debuff lands; ClassicAPI reads every debuff's school and caster, UnitXP / ClassicAPI check range and sight, SuperWoW cures without swapping your target." },
    { "Cleansing totems", "for shamans on by default, with the totem's own icon. Choose where it runs (raids, dungeons, battlegrounds, arenas, world); title bar can hide until you mouse over it; right-click its box in layout mode for its options." },
  } },
  { "1.1.40", {
    { "Mail sends everything in one press", "every queued item goes back to back, the next mail the moment the server accepts the last one (no pauses). A mail the server refuses once is tried again instead of stopping the whole run." },
    { "Update window", "when someone in your guild or group runs a newer pfUI Octo, a small window at login shows the OctoLauncher link (Copy button), what to do, and what's new since your version. \"Remind me later\" or \"Don't show for this version\"; switch it off in Settings > Scale, profiles and look; /octoupdate opens it. New file: restart the game fully once." },
    { "/pfperf events", "also counts how often the action bar events fire." },
  } },
  { "1.1.39", {
    { "Uses ClassicAPI to do less work", "25 every-few-seconds checks run on ClassicAPI's timers instead of being asked every frame; cast bars wake on the game's cast events and rest when nobody casts; action bars learn range changes from the game instead of checking every button 5 times a second; the range scan stops (ClassicAPI already answers); gathering arrows and pfQuest's route rest while you stand still. Each one keeps the old way until its event has really been seen, so nothing changes without ClassicAPI." },
    { "/pfperf events", "(and the end of Copy all) shows which ClassicAPI events and timers are in use." },
  } },
  { "1.1.38", {
    { "Mail: sending many items works", "With several items queued, Send stopped after the first mail. Now every item goes, one mail each. If a mail can't go (wrong name, mailbox closed, an item that won't attach or stays locked), sending stops and says why and how many went. The items that went come off the list, so Send again only sends the rest." },
  } },
}
